```c
// ggml-cpu flash_attn_ext: a -inf attention score at the FIRST key turns the output row into NaN.
// The same three keys in a different order (the -inf score at the LAST key) give the correct, finite result.
//
// One query, three keys, head dim 4, scale 1/sqrt(4) = 0.5, no mask, F32 q/k/v.
//   q  = [1, 0, 0, 0]
//   key with score -inf : k = [-inf, 0, 0, 0], v = [10, 10, 10, 10]   (weight must be exactly 0)
//   key with score 0.5  : k = [ 1,   0, 0, 0], v = [ 1,  1,  1,  1]
//   key with score 1.0  : k = [ 2,   0, 0, 0], v = [ 2,  2,  2,  2]
// softmax over {-inf, 0.5, 1.0} = {0, 1/(1+e^0.5), e^0.5/(1+e^0.5)} -> every output element = 1 + e^0.5/(1+e^0.5).
#include <math.h>
#include <stdio.h>
#include "ggml.h"
#include "ggml-cpu.h"

static void run(int neginf_first, int n_threads) {
    struct ggml_init_params ip = { 16 * 1024 * 1024, NULL, false };
    struct ggml_context * ctx = ggml_init(ip);
    const int D = 4, NKV = 3;
    struct ggml_tensor * q = ggml_new_tensor_2d(ctx, GGML_TYPE_F32, D, 1);
    struct ggml_tensor * k = ggml_new_tensor_2d(ctx, GGML_TYPE_F32, D, NKV);
    struct ggml_tensor * v = ggml_new_tensor_2d(ctx, GGML_TYPE_F32, D, NKV);
    float * qd = (float *) q->data, * kd = (float *) k->data, * vd = (float *) v->data;
    for (int i = 0; i < D; i++) qd[i] = (i == 0) ? 1.0f : 0.0f;
    const float k0[NKV] = { -INFINITY, 1.0f, 2.0f };   // first component of each key, in "natural" order
    const float vv[NKV] = { 10.0f, 1.0f, 2.0f };
    for (int j = 0; j < NKV; j++) {
        int src = neginf_first ? j : (j + 1) % NKV;    // order A: (-inf, 1, 2); order B: (1, 2, -inf)
        for (int i = 0; i < D; i++) {
            kd[j * D + i] = (i == 0) ? k0[src] : 0.0f;
            vd[j * D + i] = vv[src];
        }
    }
    struct ggml_tensor * out = ggml_flash_attn_ext(ctx, q, k, v, NULL, 0.5f, 0.0f, 0.0f);
    struct ggml_cgraph * gf = ggml_new_graph(ctx);
    ggml_build_forward_expand(gf, out);
    ggml_graph_compute_with_ctx(ctx, gf, n_threads);
    const float * o = (const float *) out->data;
    printf("-inf score at %-10s n_threads=%d : out = [%g, %g, %g, %g]\n",
           neginf_first ? "FIRST key," : "LAST key,", n_threads, o[0], o[1], o[2], o[3]);
    ggml_free(ctx);
}

int main(void) {
    const double e = exp(0.5);
    printf("expected (any key order)          : out = [%.6f x 4]\n", 1.0 + e / (1.0 + e));
    for (int t = 1; t <= 4; t *= 4) {
        run(1, t);
        run(0, t);
    }
    return 0;
}
```

